/// MOC 名（大小写不敏感）→ 表 id
pub fn gen_moc_index(name: &[u8]) -> Option<usize> {
    if name.is_empty() || name.len() > 16 {
        return None;
    }
    let mut buf = [0u8; 16];
    for (i, &c) in name.iter().enumerate() {
        buf[i] = c.to_ascii_uppercase();
    }
    MOCS.binary_search_by(|m| m.as_bytes().cmp(&buf[..name.len()]))
        .ok()
}

